    train = pd.merge(train_raw, meal, on="meal_id", how="left")
else:
    # Try alternative column names if meal_id doesn't exist
    if 'meal' in train_raw.columns:
        train = pd.merge(train_raw, meal, left_on="meal", right_on="meal_id", how="left")
    else:
        # Find common columns or use the right column to merge
        train = train_raw.merge(meal, left_index=True, right_index=True, how="left")

if 'center_id' in train.columns and 'center_id' in centerinfo.columns:
    df = pd.merge(train, centerinfo, on="center_id", how="left")
else:
    df = train

